# Surah Al-A'raf (chapter 7) — part 8: ayat 71-80 (IDs 1025-1034)
SURAH = 7

ENTRIES = {
1025: (
"ہودؑ نے کہا — تم پر — تمہارے رب — کی طرف سے — نفرت اور غضب نازل ہو گا — کیا — تم — مجھ سے — ان — ناموں کے بارے میں جھگڑتے ہو — جو — تم — اور تمہارے باپ دادا نے گھڑے — اللہ نے — اس — کی کوئی دلیل — نازل نہیں کی — پس — انتظار کرو — بے شک — میں — تم — کے ساتھ — انتظار کرنے والوں میں سے ہوں",
"""۱۔ ہودؑ — عاد کو — عذاب کی خبر دیتے ہیں۔
۲۔ ’’قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَادِلُونَنِي فِي أَسْمَاءٍ سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا نَزَّلَ اللَّهُ بِهَا مِن سُلْطَانٍ فَانتَظِرُوا إِنِّي مَعَكُم مِّنَ الْمُنتَظِرِينَ‘‘ — ہودؑ نے کہا — تم پر — تمہارے رب — کی طرف سے — نفرت اور غضب نازل ہو گا — کیا — تم — مجھ سے — ان — ناموں کے بارے میں جھگڑتے ہو — جو — تم — اور تمہارے باپ دادا نے گھڑے — اللہ نے — اس — کی کوئی دلیل — نازل نہیں کی — پس — انتظار کرو — بے شک — میں — تم — کے ساتھ — انتظار کرنے والوں میں سے ہوں — یعنی بت بغیر دلیل کے — غیبی غضب کا سبب بنے۔
۳۔ عملی سبق: دلیل کے بغیر عبادت — گمراہی — ہے؛ اللہ سے — خوف اور — امید رکھو۔"""
),
1026: (
"پس — ہم نے اسے — اور اس کے ساتھیوں کو — اپنی رحمت سے — بچایا — اور — جنہوں نے — ہماری آیات کو جھٹلایا — ان کی جڑ کاٹ دی — اور وہ — ایمان نہیں لائے",
"""۱۔ عاد — ہلاک؛ مومنین — نجات۔
۲۔ ’’فَأَنجَيْنَاهُ وَالَّذِينَ مَعَهُ بِرَحْمَۃٍ مِّنَّا وَقَطَعْنَا دَابِرَ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَمَا كَانُوا مُؤْمِنِينَ‘‘ — پس — ہم نے اسے — اور اس کے ساتھیوں کو — اپنی رحمت سے — بچایا — اور — جنہوں نے — ہماری آیات کو جھٹلایا — ان کی جڑ کاٹ دی — اور وہ — ایمان نہیں لائے — یعنی جھٹلانے والوں کا — نسل سمیت خاتمہ — ہو گیا۔
۳۔ عملی سبق: ایمان والے — اللہ کی رحمت میں محفوظ ہیں۔"""
),
1027: (
"اور — ثمود کی طرف — ان کے بھائی صالحؑ کو بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ — کوئی الٰہ نہیں — بے شک — تمہارے پاس — تمہارے رب کی طرف سے — ایک واضح نشانی آئی — یہ — اللہ کی ناقہ ہے — تمہارے لیے — نشانی — اسے — چھوڑو کہ — اللہ کی زمین میں — چرتی رہے — اور — اسے — برا ارادہ نہ کرو — ورنہ — تمہیں — دردناک عذاب دیکھے گا",
"""۱۔ صالحؑ — ثمود کی طرف — اور اللہ کی نشانی — ناقہ۔
۲۔ ’’وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ قَدْ جَاءَتْكُم بَيِّنَۃٌ مِّن رَّبِّكُمْ هَٰذِهِ نَاقَۃُ اللَّهِ لَكُمْ آيَۃً فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ‘‘ — اور — ثمود کی طرف — ان کے بھائی صالحؑ کو بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ — کوئی الٰہ نہیں — بے شک — تمہارے پاس — تمہارے رب کی طرف سے — ایک واضح نشانی آئی — یہ — اللہ کی ناقہ ہے — تمہارے لیے — نشانی — اسے — چھوڑو کہ — اللہ کی زمین میں — چرتی رہے — اور — اسے — برا ارادہ نہ کرو — ورنہ — تمہیں — دردناک عذاب دیکھے گا — یعنی ناقہ — اللہ کی نشانی تھی — ثمود کو اسے اذیت نہ دینے کا حکم تھا۔
۳۔ عملی سبق: اللہ کی نشانیوں کا احترام کرو۔"""
),
1028: (
"اور — یاد کرو — جب اس نے — تمہیں — عاد کے بعد — جانشین بنایا — اور — تمہیں — زمین میں — رہنے کو دی — اس کے میدانوں میں — تم — محل بناتے ہو — اور — پہاڑوں سے — گھر — تراشتے ہو — پس — اللہ کی نعمتوں کو یاد کرو — اور — زمین میں — فساد مت پھیلاؤ",
"""۱۔ ثمود کو — طاقت و وسعت — اللہ کی نعمت۔
۲۔ ’’وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفَاءَ مِن بَعْدِ عَادٍ وَبَوَّأَكُمْ فِي الْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ الْجِبَالَ بُيُوتًا فَاذْكُرُوا آلَاءَ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ‘‘ — اور — یاد کرو — جب اس نے — تمہیں — عاد کے بعد — جانشین بنایا — اور — تمہیں — زمین میں — رہنے کو دی — اس کے میدانوں میں — تم — محل بناتے ہو — اور — پہاڑوں سے — گھر — تراشتے ہو — پس — اللہ کی نعمتوں کو یاد کرو — اور — زمین میں — فساد مت پھیلاؤ — یعنی ثمود کو حکمت اور طاقت ملی — مگر — وہ — اسے فساد کے لیے استعمال کرتے رہے۔
۳۔ عملی سبق: طاقت و وسعت — شکر اور انصاف کی — ذمہ داری ہے۔"""
),
1029: (
"ان کی قوم کے تکبر والے سرداروں نے — ان — کمزور ایمانداروں سے — پوچھا — کیا تم — جانتے ہو کہ — صالحؑ — اپنے رب — کی طرف سے — بھیجے گئے ہیں — انہوں نے کہا — بے شک — ہم — اس — رسالت کے — ماننے والے ہیں",
"""۱۔ ثمود — طبقاتی تفریق — ایمان پر۔
۲۔ ’’قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِن قَوْمِهِ لِلَّذِينَ اسْتُضْعِفُوا لِمَنْ آمَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَالِحًا مُّرْسَلٌ مِّن رَّبِّهِ قَالُوا إِنَّا بِمَا أُرْسِلَ بِهِ مُؤْمِنُونَ‘‘ — ان کی قوم کے تکبر والے سرداروں نے — ان — کمزور ایمانداروں سے — پوچھا — کیا تم — جانتے ہو کہ — صالحؑ — اپنے رب — کی طرف سے — بھیجے گئے ہیں — انہوں نے کہا — بے شک — ہم — اس — رسالت کے — ماننے والے ہیں — یعنی کمزور مسلمان — مضبوط ایمان والے — نبی کی تصدیق کرتے ہیں۔
۳۔ عملی سبق: ایمان کی قوت — کمزور طبقے میں — بھی پختہ ہو سکتی ہے۔"""
),
1030: (
"تكبر کرنے والوں نے کہا — بے شک — ہم — اس — پر — جس — پر تم ایمان لائے ہو — کافروں میں سے ہیں",
"""۱۔ تکبر والے — اعلانِ کفر۔
۲۔ ’’قَالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا بِالَّذِي آمَنتُم بِهِ كَافِرُونَ‘‘ — تکبر کرنے والوں نے کہا — بے شک — ہم — اس — پر — جس — پر تم ایمان لائے ہو — کافروں میں سے ہیں — یعنی سردار — کھل کر — کفر کا اعلان کرتے ہیں۔
۳۔ عملی سبق: تکبر — آدمی کو کھل کر — انکارِ حق تک لے جاتا ہے۔"""
),
1031: (
"پس — انہوں نے — ناقہ — کاٹ ڈالی — اور — اپنے رب کے حکم سے — سرپیچی کی — اور کہا — اے صالح — لاؤ — جو — تم — ہمیں — ایفائے وعدہ کرتے ہو — اگر — تم رسول ہو",
"""۱۔ ناقہ کا ذبح — کھلا بغاوت۔
۲۔ ’’فَعَقَرُوا النَّاقَۃَ وَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا يَا صَالِحُ ائْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الْمُرْسَلِينَ‘‘ — پس — انہوں نے — ناقہ — کاٹ ڈالی — اور — اپنے رب کے حکم سے — سرپیچی کی — اور کہا — اے صالحؑ — لاؤ — جو — تم — ہمیں — ایفائے وعدہ کرتے ہو — اگر — تم رسول ہو — یعنی ثمود نے — ہودؑ کے حکم کی — کھل کر خلاف ورزی کی۔
۳۔ عملی سبق: اللہ کی نشانیوں کا — توڑ — دردناک انجام — کی طرف لے جاتا ہے۔"""
),
1032: (
"پس — انہیں — زلزلہ — آ لیا — اور — وہ — اپنے گھروں میں — مسبج بیٹھے رہ گئے",
"""۱۔ ثمود — زلزلے میں — ہلاک۔
۲۔ ’’فَأَخَذَتْهُمُ الرَّجْفَۃُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ‘‘ — پس — انہیں — زلزلہ — آ لیا — اور — وہ — اپنے گھروں میں — منہ — کے بل گرے ہوئے — پڑے رہے — یعنی ایک لمحے میں پوری قوم — ختم۔
۳۔ عملی سبق: اللہ کا عذاب آتے دیر نہیں لگتی۔"""
),
1033: (
"پس — صالحؑ — ان سے — غزونگاہ لوٹ آئے — اور کہا — اے میری قوم — بے شک — میں نے — تمہیں — اپنے رب کا پیغام — پہنچایا — اور — تمہاری خیر خواہی کی — لیکن — تم — خیرخواہوں سے — محبت نہیں کرتے",
"""۱۔ صالحؑ — قوم سے — الوداع۔
۲۔ ’’فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَۃَ رَبِّي وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ النَّاصِحِينَ‘‘ — پس — صالحؑ — ان سے — واپس لوٹ آئے — اور کہا — اے میری قوم — بے شک — میں نے — تمہیں — اپنے رب کا پیغام — پہنچایا — اور — تمہاری خیر خواہی کی — لیکن — تم — خیرخواہوں سے — محبت نہیں کرتے — یعنی قوم نے — مرنے کے بعد بھی — توبہ نہ کی — ہودؑ ناراض ہو کر چلے گئے۔
۳۔ عملی سبق: نصیحت قبول کرنا — بڑی کامیابی ہے۔"""
),
1034: (
"اور — لوطؑ کو بھی بھیج — جب — انہوں نے — اپنی قوم سے کہا — کیا تم — بے حیائی کرتے ہو — جس کا — تم سے پہلے — کوئی نہیں کرتا تھا",
"""۱۔ لوطؑ — اپنی قوم کی بے حیائی کی مذمت کرتے ہیں۔
۲۔ ’’وَلُوطًا إِذْ قَالَ لِقَوْمِهِ أَتَأْتُونَ الْفَاحِشَۃَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ‘‘ — اور — لوطؑ کو بھی بھیج — جب — انہوں نے — اپنی قوم سے کہا — کیا تم — بے حیائی کرتے ہو — جس کا — تم سے پہلے — کوئی نہیں کرتا تھا — یعنی قوم لوطؑ — بدکاری میں — پوری دنیا میں منفرداور پہلی قوم تھی۔
۳۔ عملی سبق: بے حیائی — اخلاقی زوال کی سب سے واضح علامت — ہے۔"""
),
}
